ALTER TABLE tventas ENABLE ROW LEVEL SECURITY;
ALTER TABLE tventas FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_tventas ON tventas FOR ALL
USING (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid)
WITH CHECK (papeleria_id = NULLIF(current_setting('app.current_tenant_id', true),'')::uuid);
CREATE OR REPLACE FUNCTION set_current_tenant(p UUID) RETURNS void AS $$
BEGIN PERFORM set_config('app.current_tenant_id', p::text, true); END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION generate_uuid_v7() RETURNS uuid AS $$
DECLARE v_time timestamptz := clock_timestamp(); v_secs bigint; v_msec bigint; v_buf bytea;
BEGIN
v_secs := EXTRACT(EPOCH FROM v_time)::bigint;
v_msec := (v_secs * 1000) + (EXTRACT(MILLISECONDS FROM v_time)::bigint % 1000);
v_buf := decode(lpad(to_hex(v_msec), 12, '0') || encode(gen_random_bytes(10), 'hex'), 'hex');
v_buf := set_byte(v_buf, 6, (get_byte(v_buf, 6) &amp; 15) | 112);
v_buf := set_byte(v_buf, 8, (get_byte(v_buf, 8) &amp; 63) | 128);
RETURN encode(v_buf, 'hex')::uuid;
END;
$$ LANGUAGE plpgsql VOLATILE;

llm_gateway.codigo:
# src/application/services/llm_gateway.py
import hashlib, os, re
from typing import Literal
from src.infrastructure.db.models import TLLMBudgetLog

class LLMGateway:
    def __init__(self):
        self.providers = {
            "deepseek": DeepSeekClient(),
            "openai": OpenAIClient(),
            "claude": ClaudeClient(),
            "qwen": QwenClient(),
            "kimi": KimiClient(),
            "local": LocalModelClient() # vLLM/Ollama para privacidad y reducción de costos
        }
        self.budget_tracker = BudgetTracker()

    async def generate(self, session, tenant_id, *, prompt, task_type="customer_facing", max_tokens=500, temperature=0.3) -> str:
        presupuesto = await self._presupuesto_restante(session, tenant_id)
        if presupuesto &lt; 0.2 * 200000: task_type = "interno_barato" # Forzar barato

        if len(prompt) > 8000 * 4: provider_name = "claude"
        elif task_type == "tarea_critica": provider_name = "openai"
        elif task_type == "customer_facing": provider_name = "openai"
        elif task_type == "largo_contexto": provider_name = "claude"
        else: provider_name = "deepseek" # Default barato

        safe_prompt = self._mask_pii(prompt)
        try:
            return await self.providers[provider_name].generate(safe_prompt, max_tokens, temperature)
        except Exception:
            for fb in ["openai", "deepseek", "local"]:
                if fb == provider_name: continue
                try: return await self.providers[fb].generate(safe_prompt, max_tokens, temperature)
                except Exception: continue
            raise LLMGatewayError("Todos los proveedores fallaron")

    def _mask_pii(self, prompt: str) -> str:
        return re.sub(r'\+?52\d{10}', lambda m: f"HASH_{hashlib.sha256(m.group().encode()).hexdigest()[:8]}", prompt)
